import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"12、【否】 坤下乾上","description":"周易尚氏學 - 12、【否】 坤下乾上","frontmatter":{"title":"12、【否】 坤下乾上","description":"周易尚氏學 - 12、【否】 坤下乾上"},"headers":[],"relativePath":"classics/shangshi/017.md","filePath":"classics/shangshi/017.md"}'),s={name:"classics/shangshi/017.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_12、【否】-坤下乾上" tabindex="-1">12、【否】 坤下乾上 <a class="header-anchor" href="#_12、【否】-坤下乾上" aria-label="Permalink to “12、【否】 坤下乾上”">​</a></h1><p>陽上升。陰下降。乃陽即在上。陰即在下。愈去愈遠。故天地不交而為否。否閉也。泰上六象傳雲其命亂也。言泰極反否。乃天地自然之命運。必至之理。非人力所能為。此曰否之匪人。仍其義也。陽往外而詘。陰來內而信。故不利君子貞。貞卜問。其以正為說者。無論若何斡旋。皆不能通。</p><p>彖曰。否之匪人。不利君子貞，大往小來。則是天地不交。而萬物不通也。上下不交。而天下無邦也。內陰而外陽。內柔而外剛。內小人而外君子。小人道長。君子道消也。</p><p>天氣本上騰而在外。地氣本下降而在內。愈去愈遠。故氣不交。氣不交故萬物不通而死矣。坤為萬物為邦國。乾上坤下。君民不親。上下閉塞。而邦必亂。故曰無邦。否七月卦。陰長陽消。故曰小人道長。君子道消。</p><p>象曰。天地不交。否。君子以儉德闢難。不可榮以祿。</p><p>乾為德。儉約也。坤閉故曰儉德。言斂抑自守也。互巽為伏。故曰闢難。坤為患為難。言遁世不出。以避世難。乾為祿。艮為榮。巽伏故不可榮以祿位。言當否之時。遁人山林。高隱不出也。</p><p>初六。拔茅茹以其匯。徵吉。亨。</p><p>陰皆有應。故辭與泰同。泰茅茹象。指應爻。此則用本象也。</p><h3 id="象曰。拔茅徵吉。志在君也。" tabindex="-1">象曰。拔茅徵吉。志在君也。 <a class="header-anchor" href="#象曰。拔茅徵吉。志在君也。" aria-label="Permalink to “象曰。拔茅徵吉。志在君也。”">​</a></h3><p>坤為志。乾為君。志在君。言上應四也。</p><p>六二。苞承。小人吉。大人否亨。</p><p>苞今本作包。依唐石經及釋文。下同。包苞古通用。禹貢。草木漸包。注包叢生。釋文。字亦作苞。是包苞古不分。爾雅釋言云苞稹也。疏。孫炎曰。物叢生曰苞。詩唐風。集於苞栩。亦以苞為叢。是苞有多意。眾義。坤為眾。苞承者。言下三爻皆承陽有應也。小人謂二。二得中有應。故小人吉。凡陰得陽應必吉。陽得陰應不皆吉。而否卦陽氣上騰。不能下降。故大人否亨。大人謂五。否不。言五雖得二應而不亨也。朱升釋承為脀。卦既無此象。荀爽謂二為四所包。朱震謂二為五所包。夫四五若能下施包二。則大人不否亨矣。非也。</p><h3 id="象曰。大人否亨。不亂群也。" tabindex="-1">象曰。大人否亨。不亂群也。 <a class="header-anchor" href="#象曰。大人否亨。不亂群也。" aria-label="Permalink to “象曰。大人否亨。不亂群也。”">​</a></h3><p>坤眾放曰群。坤為亂。亂雜也。不亂群。言五不能下施應二。俾天地相雜也。故否亨。虞翻謂坤三陰。亂弒君。大人不從。故不亂群。豈知不亂群。即仍天地不交之義。言五不能交二也。群義即釋苞義也。</p><p>六三。苞羞。</p><p>此苞字與上同義。仍坤眾坤群象也。羞。說文進獻也。左傳隱三年。潤溪沼沚之毛。可薦於鬼神。可羞於王公。杜注羞進也。國語楚語下。於是乎每朝設脯一束。以羞子文。注亦作進。苞羞者眾進也。否本陰長之卦。故群進而消陽也。</p><h3 id="象曰。苞羞。位不當也。" tabindex="-1">象曰。苞羞。位不當也。 <a class="header-anchor" href="#象曰。苞羞。位不當也。" aria-label="Permalink to “象曰。苞羞。位不當也。”">​</a></h3><p>六三不當位。進至於四。或與上相上下。則當位矣。言所以進者。以不當位也。釋苞羞之故也。自荀爽釋為羞恥。朱升釋為膳羞。位不當之義。皆莫知所指矣。</p><p>九四。有命。無咎。疇離祉。</p><p>命。說文使也。廣韻召也。有命言有所使命也。巽為命。周語襄王錫晉文公命。蓋四履群陰之上。萬民(坤為民)順承。故有所錫命。四不當位。宜有咎。得群陰使命。故無咎。頤上九雲。利涉大川。與此義同也。疇儔同。荀子勸學篇雲。草木疇生。注疇同儔。前漢韓信傳。其疇十三人。義亦同儔。儔眾也。下坤為眾。離附著。祉福。疇離祉者。言眾陰同附陽。得主而受福也。孔疏訓疇為匹。匹謂初。言初得陽應而受福。然象釋曰志行。荀爽謂志行於群陰。固統三陰言。不專指初也。</p><h3 id="象曰。有命無咎。志行也。" tabindex="-1">象曰。有命無咎。志行也。 <a class="header-anchor" href="#象曰。有命無咎。志行也。" aria-label="Permalink to “象曰。有命無咎。志行也。”">​</a></h3><p>四履重陰。得行其志。故曰志行。</p><p>九五。體否。大人吉。其亡其亡。繫於苞桑。</p><p>說文人依木則休。休者憩息也。休否者。言當否之時。而休息以俟也。蓋初四三上相上下。則既濟成。五當位居中。宜靜俟也。舊解釋為休美。與其亡義背。似非也。九五為大人。故曰大人吉。九五巽體。巽為桑。坤為多。故曰苞桑。陸績京氏易傳注云。苞桑則叢桑也。巽為繩。為系。故曰繫於苞桑。乃巽為隕落。五雖居中得正。而風隕在下。故有其亡之懼。蓋系在大木。方能鞏固。桑而叢生。其柔可知。繫於柔木。其危可知。其亡其亡。繫於苞桑者。言時時慮亡。如繫於苞桑之不足恃也。王陶廬雲。唐石經初刻作包。後增改作苞。按禹貢草木漸包。傳釋為叢生。仍與苞同。自風隕象失傳。後儒不知危亡之故。在五履巽。於是舊解皆以堅固為說。遂與易象不協矣。</p><h3 id="象曰。大人之吉。位正當也。" tabindex="-1">象曰。大人之吉。位正當也。 <a class="header-anchor" href="#象曰。大人之吉。位正當也。" aria-label="Permalink to “象曰。大人之吉。位正當也。”">​</a></h3><p>五位尊而中正。故曰位當。</p><p>上九。傾否。先否後喜。</p><p>侯果曰。傾覆也。上應在三。三巽為隕落。故曰傾否。言傾否而出之盡也。然當未覆之先。則仍否也。故曰先否。上反下則成震。震為樂為後。故曰後喜。</p><h3 id="象曰。否終則傾。何可長也。" tabindex="-1">象曰。否終則傾。何可長也。 <a class="header-anchor" href="#象曰。否終則傾。何可長也。" aria-label="Permalink to “象曰。否終則傾。何可長也。”">​</a></h3><p>否終則傾。言否終則泰復。不能長否。按否泰雲。大小往來。無平不陂。無往不復。終則曰城復於隍。其命亂也。否則曰否之匪人。皆言天地否泰之運。循環往來。自然如此。不假人為。為上經天地水火之樞紐。明天道本如斯。不可易也。至下經第十卦之損益。則曰損益盈虛。與時偕行。曰損剛益柔。曰損下益上。損上益下。曰見善則遷。有過則改。所言皆履世之大經。修治之極軌。無絲毫委心任運之意。以為鹹恆既未濟之樞紐。明人事宜如斯也。盡人事。聽天命。斯學易之功也。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
